    constexpr static int kBlockN = 256;

    run_flash_splitkv_fwd<Flash_fwd_kernel_traits<Headdim, kBlockM, kBlockN, 4, false, false, quant_mode, num_bits, group_size, T>, Is_causal>(params, stream);
}


